CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE storage_nodes (id TEXT PRIMARY KEY, name TEXT NOT NULL, path TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ONLINE' CHECK(status IN ('ONLINE','OFFLINE')), capacity BIGINT NOT NULL DEFAULT 10737418240, used_space BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_heartbeat TIMESTAMPTZ);
CREATE TABLE chunks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hash CHAR(64) UNIQUE NOT NULL, size INTEGER NOT NULL, reference_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE chunk_replicas (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), chunk_id UUID NOT NULL REFERENCES chunks(id) ON DELETE CASCADE, node_id TEXT NOT NULL REFERENCES storage_nodes(id), storage_key TEXT NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(chunk_id,node_id));
CREATE TABLE files (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES users(id), name VARCHAR(255) NOT NULL, mime_type VARCHAR(255), logical_size BIGINT NOT NULL DEFAULT 0, current_version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE file_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), file_id UUID NOT NULL REFERENCES files(id) ON DELETE CASCADE, version INTEGER NOT NULL, size BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(file_id,version));
CREATE TABLE file_chunks (file_version_id UUID NOT NULL REFERENCES file_versions(id) ON DELETE CASCADE, chunk_id UUID NOT NULL REFERENCES chunks(id), sequence INTEGER NOT NULL, PRIMARY KEY(file_version_id,sequence));
CREATE TABLE file_shares (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), file_id UUID NOT NULL REFERENCES files(id) ON DELETE CASCADE, owner_id UUID NOT NULL REFERENCES users(id), shared_with_user_id UUID NOT NULL REFERENCES users(id), permission TEXT NOT NULL CHECK(permission IN ('VIEW','DOWNLOAD')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(file_id,shared_with_user_id));
CREATE TABLE upload_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES users(id), filename TEXT NOT NULL, mime_type TEXT, total_size BIGINT NOT NULL, chunk_size INTEGER NOT NULL, total_chunks INTEGER NOT NULL, received_chunks INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE upload_chunks (session_id UUID REFERENCES upload_sessions(id) ON DELETE CASCADE, sequence INTEGER NOT NULL, chunk_id UUID REFERENCES chunks(id), PRIMARY KEY(session_id,sequence));
CREATE INDEX idx_file_chunks_chunk ON file_chunks(chunk_id); CREATE INDEX idx_replicas_chunk ON chunk_replicas(chunk_id); CREATE INDEX idx_shares_user ON file_shares(shared_with_user_id);
INSERT INTO storage_nodes (id,name,path) VALUES ('node-1','Storage Node 1','/storage/node-1'),('node-2','Storage Node 2','/storage/node-2'),('node-3','Storage Node 3','/storage/node-3') ON CONFLICT DO NOTHING;
